1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { apiFetch } from '../lib/api';
4	  import { sessionStore } from '../stores/session.svelte';
5	
6	  type LoadState = 'idle' | 'loading' | 'done' | 'error';
7	
8	  type OpportunityItem = Record<string, string>;
9	
10	  let state = $state<LoadState>('idle');
11	  let opportunities = $state<OpportunityItem[]>([]);
12	  let errorMessage = $state<string | null>(null);
13	
14	  const sessionHeaders = (): Record<string, string> =>
15	    sessionStore.sessionId ? { 'X-Autom9-Session': sessionStore.sessionId } : {};
16	
17	  function badgeLabel(type: string): string {
18	    return type === 'billable' ? 'Billable' : 'Internal';
19	  }
20	
21	  function fieldEntries(opp: OpportunityItem): [string, string][] {
22	    return Object.entries(opp).filter(([key, value]) => key !== 'type' && Boolean(value));
23	  }
24	
25	  async function loadOpenWork(): Promise<void> {
26	    state = 'loading';
27	    try {
28	      const response = await apiFetch<{ data: OpportunityItem[] }>('/api/data/open-work', {
29	        headers: sessionHeaders(),
30	      });
31	      opportunities = response.data;
32	      state = 'done';
33	    } catch {
34	      errorMessage = 'Could not load open work opportunities';
35	      state = 'error';
36	    }
37	  }
38	
39	  onMount(() => {
40	    loadOpenWork();
41	  });
42	</script>
43	
44	<div class="open-work-panel">
45	  <section class="panel-section">
46	    <h3>Open Work Opportunities</h3>
47	    {#if state === 'loading'}
48	      <p class="loading">Loading…</p>
49	    {:else if state === 'error'}
50	      <p class="error">{errorMessage}</p>
51	    {:else if opportunities.length === 0}
52	      <p class="empty">No open work opportunities available</p>
53	    {:else}
54	      <ul>
55	        {#each opportunities as opp}
56	          <li class="opportunity">
57	            {#if opp.type}
58	              <span class="badge badge-{opp.type}">{badgeLabel(opp.type)}</span>
59	            {/if}
60	            <div class="opportunity-fields">
61	              {#each fieldEntries(opp) as [key, value] (key)}
62	                <span class="field field-{key}">{value}</span>
63	              {/each}
64	            </div>
65	          </li>
66	        {/each}
67	      </ul>
68	    {/if}
69	  </section>
70	</div>
71	
72	<style>
73	  .open-work-panel {
74	    font-family: sans-serif;
75	    padding: 0.75rem;
76	  }
77	  .panel-section {
78	    margin-bottom: 1.25rem;
79	  }
80	  h3 {
81	    font-size: 0.875rem;
82	    font-weight: 600;
83	    margin: 0 0 0.5rem;
84	    text-transform: uppercase;
85	    letter-spacing: 0.05em;
86	    color: #444;
87	  }
88	  .loading { color: #666; font-style: italic; }
89	  .error { color: #c00; }
90	  .empty { color: #888; }
91	  ul {
92	    margin: 0;
93	    padding: 0;
94	    list-style: none;
95	  }
96	  .opportunity {
97	    display: flex;
98	    align-items: flex-start;
99	    gap: 0.5rem;
100	    padding: 0.4rem 0;
101	    font-size: 0.875rem;
102	    border-bottom: 1px solid #f0f0f0;
103	  }
104	  .opportunity:last-child {
105	    border-bottom: none;
106	  }
107	  .badge {
108	    flex-shrink: 0;
109	    font-size: 0.7rem;
110	    font-weight: 600;
111	    padding: 0.1rem 0.4rem;
112	    border-radius: 3px;
113	    white-space: nowrap;
114	    text-transform: uppercase;
115	    letter-spacing: 0.03em;
116	    margin-top: 0.1rem;
117	  }
118	  .badge-billable {
119	    background: #e6f4ea;
120	    color: #137333;
121	  }
122	  .badge-internal {
123	    background: #e8eaf6;
124	    color: #3949ab;
125	  }
126	  .opportunity-fields {
127	    display: flex;
128	    flex-direction: column;
129	    gap: 0.15rem;
130	    min-width: 0;
131	  }
132	  .field {
133	    color: #222;
134	  }
135	  .field-title {
136	    font-weight: 500;
137	  }
138	  .field-details {
139	    color: #555;
140	    font-size: 0.8rem;
141	    white-space: pre-wrap;
142	  }
143	</style>
